//! What the Linux rows carry (docs/operator.md, The platform seam, the bootstrap and sync rows;
//! D37's addendum, D46): `box\bootstrap.sh` and `box\system`, embedded at build time byte for byte
//! as they are in the repository, as `agentspace-sync` embeds them today.
//!
//! RFC 2119 keywords, and the capitals are load-bearing.
//!
//! These bytes MUST NOT be re-authored, filtered or converted. A test compares them with the
//! repository's files.

// `BOX_SYSTEM`: every file of the repository's `box\system`, generated by build.rs.
include!(concat!(env!("OUT_DIR"), "/box_system.rs"));

/// The repository's `box\bootstrap.sh`, the toolchain bootstrap (operator.md, bootstrap; D46),
/// sent to the host on an ssh's stdin and never written to a file on the laptop.
pub(crate) const BOOTSTRAP: &[u8] = include_bytes!("../../../box/bootstrap.sh");
